public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node is null or has no right child
    if (node == null || node.getRight() == null) {
        // No rotation possible, return the original node
        return node;
    }

    // Get the left child and its right child
    TreeNode<T> left = node.getLeft();
    TreeNode<T> right = node.getRight();

    // Set the parent of the right child to be the new parent of the node
    right.setParent(node.getParent());

    // Set the left child of the node to be the right child of the old parent
    node.getParent().setRight(right);

    // Set the left child of the old parent to be the node
    node.getParent().setLeft(left);

    // Set the right child of the node to be the left child of the new parent
    node.setRight(node.getParent());

    // Set the parent of the node to be the old parent of the right child
    node.getParent().setParent(right.getParent());

    // Return the new parent of the node
    return node.getParent();
}

