    TreeNode<T> left = node.getLeft();

    // Step 2: Get the right child of the left child of the input node
    TreeNode<T> leftRight = left.getRight();

    // Step 3: Perform the rotation
    node.setRight(left.getLeft());
    left.setLeft(node);
    node.setLeft(leftRight);

    // Step 4: Return the new parent of the input node
    return left;
