private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Unbalanced tree (node does not have a left child)
    if (node.getLeft() == null) {
        return node;
    }

    // Rotate
    TreeNode<T> newParent = node.getLeft();
    newParent.setRight(node);
    node.setLeft(null);

    return newParent;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Null node");
    }
    TreeNode<T> newParent = node.getRightChild();
    if (newParent != null) {
        node.setRightChild(newParent.getLeftChild());
        newParent.setLeftChild(node);
    }
