public static int parseEndOfLine(String headerPart, int end) {
    // Skip bytes until the end of the current line
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i + 1;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    int eolIndex = headerPart.indexOf('\r', end);
    if (eolIndex >= 0 && eolIndex < headerPart.length() && headerPart.charAt(eolIndex + 1) == '\n') {
        return eolIndex + 1;
    }
    return -1;
}

public int parseEndOfLine(String headerPart, int end) {
    // Search for \r\n sequence
    int index = headerPart.indexOf("\r\n", end);

    // If \r\n sequence not found, raise exception
    if (index == -1) {
        throw new IllegalArgumentException("No end of line sequence found");
    }

    // Return index of \r\n sequence
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    // Find the end of the line
    for (int i = end; i < headerPart.length(); i++) {
        char c = headerPart.charAt(i);
        if (c == '\r' && headerPart.length() > i + 1 && headerPart.charAt(i + 1) == '\n') {
            // Found end of line
            return i + 1;
        }
    }
    // Could not find end of line
    return -1;
}

