public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Initialize a new IsomorphicGraphMapping with the same vertex set as the input graph
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>(graph.getVertexSet());

    // Loop over all vertices in the input graph
    for (V vertex : graph.getVertexSet()) {
        // Add a self-loop to the mapping for each vertex, with the edge label equal to the vertex label
        mapping.addEdge(vertex, vertex, vertex.getLabel());
    }

    // Return the constructed mapping
    return mapping;
}

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    IsomorphicGraphMapping<V, E> result = new IsomorphicGraphMapping<>();
    for (V v : graph.vertexSet()) {
        result.put(v, v);
    }
    return result;
}

