    Map<V, V> mapping = new HashMap<>();
    for (V vertex : graph.vertices()) {
        mapping.put(vertex, vertex);
    }
    return new IsomorphicGraphMapping<>(graph, mapping);
}

public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>();
    for (Vertex<V> vertex : graph.getVertices()) {
        mapping.put(vertex, vertex);
    }
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    // Check for null inputs
    if (graph == null) {
        throw new IllegalArgumentException("Input graph cannot be null.");
    }

    // Create a new IsomorphicGraphMapping with the same vertex and edge types
    IsomorphicGraphMapping<V,E> identityMap = new IsomorphicGraphMapping<>(graph.getVertexType(), graph.getEdgeType());

    // Iterate over each vertex in the graph
    for (V vertex : graph.getVertices()) {
        // Add a self-mapping for the vertex
        identityMap.addVertexMapping(vertex, vertex);
    }

    // Iterate over each edge in the graph
    for (E edge : graph.getEdges()) {
        // Add an edge mapping for the edge
        identityMap.addEdgeMapping(edge, edge);
    }

    // Return the constructed IsomorphicGraphMapping
    return identityMap;
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file.isDirectory()) {
        file.deleteOnExit();
        for (File f : file.listFiles()) {
            if (f.isDirectory()) {
                forceDeleteOnExit(f);
            } else {
                f.deleteOnExit();
            }
        }
    } else {
        file.deleteOnExit();
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    Objects.requireNonNull(file);
    if (file.isDirectory()) {
        file.deleteOnExit();
        try {
            // Delete all sub-directories
            File[] subFiles = file.listFiles();
            for (File subFile : subFiles) {
                forceDeleteOnExit(subFile);
            }
        } catch (NullPointerException e) {
            // Do nothing, file is null
        }
    } else {
        file.deleteOnExit();
    }
}

