    } else {
        deleteOnExit(file);
    }
}

private static void forceDeleteDirectoryOnExit(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    if (!directory.isDirectory()) {
        throw new IllegalArgumentException("Argument must be a directory");
    }

    for (File file : listFiles(directory)) {
        forceDelete(file);
    }
    deleteOnExit(directory);
}

private static void deleteOnExit(File file) throws IOException {
    if (!file.exists()) {
        return;
    }
    if (!file.delete()) {
        throw new IOException("Failed to delete file: " + file);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file cannot be null");
    }
    if (file.isDirectory()) {
        deleteDirectory(file);
    } else {
        if (!file.delete()) {
            throw new IOException("Could not delete file: " + file);
        }
    }
}

private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    if (!directory.isDirectory()) {
        throw new IOException("Directory does not exist or is not a directory: " + directory);
    }
    for (File file : directory.listFiles()) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            if (!file.delete()) {
                throw new IOException("Could not delete file: " + file);
            }
        }
    }
    if (!directory.delete()) {
        throw new IOException("Could not delete directory: " + directory);
    }
}

