public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    // Check if the input map and graph are valid
    if (resultMap == null || target == null) {
        throw new IllegalArgumentException("Invalid input: null map or graph");
    }

    // Loop through the result map and add vertices to the graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String name = entry.getKey();
        V value = entry.getValue();
        target.addVertex(name, value);
    }

    // Loop through the result map again and add edges to the graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String sourceName = entry.getKey();
        V sourceValue = entry.getValue();
        for (Map.Entry<String, V> neighborEntry : resultMap.entrySet()) {
            String neighborName = neighborEntry.getKey();
            if (!sourceName.equals(neighborName)) {
                V neighborValue = neighborEntry.getValue();
                target.addEdge(new E(sourceName, neighborName, sourceValue, neighborValue));
            }
        }
    }
}

