public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    // Check for null inputs
    if (out == null || message == null || schema == null) {
        throw new IllegalArgumentException("Null input(s)");
    }

    // Serialize the message
    byte[] serializedMessage = schema.toByteArray(message);
    int messageSize = serializedMessage.length;

