public static int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Check if the input is null
    if (message == null) {
        throw new IllegalArgumentException("Input message cannot be null");
    }

    // Check if the schema is null
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }

    // Check if the buffer is null
    if (buffer == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }

    // Serialize the message to a byte array
    byte[] bytes = schema.writeDelimitedTo(message, buffer);

    // Write the length of the byte array to the output stream
    out.write(bytes.length);

    // Write the byte array to the output stream
    out.write(bytes);

    // Return the size of the message
    return bytes.length;
}

