public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the genericType is parameterized and has type variables
    if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = paramType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

        // Resolve the type of each type variable using the target type
        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type typeArgument = actualTypeArguments[i];
            if (typeArgument instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) typeArgument;
                resolvedArguments[i] = resolveTypeVariable(typeVar, targetType);
            } else {
                resolvedArguments[i] = (Class<?>) typeArgument;
            }

            // Check if the resolved argument is null
            if (resolvedArguments[i] == null) {
                // Could not resolve the argument, return null
                return null;
            }
        }

        return resolvedArguments;
    }

    // If the genericType is not parameterized, return null
    return null;
}

