        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];

        for (int i = 0; i < actualTypeArguments.length; i++) {
            Type actualTypeArgument = actualTypeArguments[i];
            resolvedArguments[i] = resolveType(actualTypeArgument, targetType);
        }

        return resolvedArguments;
    }

    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || !(genericType instanceof ParameterizedType) || targetType == null) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Class<?>[] typeArguments = parameterizedType.getActualTypeArguments();
    if (typeArguments.length == 0) {
        return null;
    }

    List<Class<?>> resolvedArguments = new ArrayList<>();
    for (Type typeArgument : typeArguments) {
        Class<?> resolvedArgument = resolveType(typeArgument, targetType);
        if (resolvedArgument != null) {
            resolvedArguments.add(resolvedArgument);
        }
    }

    return resolvedArguments.toArray(new Class<?>[] { });
}

public static Class<?> resolveType(Type type, Class<?> targetType) {
    if (type == null || targetType == null) {
        return null;
    }

    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }

    if (type instanceof ParameterizedType) {
        return resolveArguments((ParameterizedType) type, targetType);
    }

    if (type instanceof GenericArrayType) {
        return resolveGenericArrayType((GenericArrayType) type, targetType);
    }

    if (type instanceof TypeVariable<?>) {
        return resolveTypeVariable((TypeVariable<?>) type, targetType);
    }

    return null;
}

private static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        // Get the type arguments as a list
        Type[] typeArgs = ((ParameterizedType) genericType).getActualTypeArguments();
        if (typeArgs.length == 0) {
            return null;
        }
        // Create an array to store the resolved arguments
        Class<?>[] resolvedArgs = new Class<?>[typeArgs.length];
        for (int i = 0; i < typeArgs.length; i++) {
            Type typeArg = typeArgs[i];
            if (typeArg instanceof Class) {
                resolvedArgs[i] = (Class<?>) typeArg;
            } else if (typeArg instanceof GenericArrayType) {
                // Handle arrays of generic types
                resolvedArgs[i] = resolveArguments(((GenericArrayType) typeArg).getGenericComponentType(), targetType)[0];
                if (resolvedArgs[i] == null) {
                    resolvedArgs[i] = Object.class;
                }
            } else {
                // Handle generic type variables
                resolvedArgs[i] = resolveArguments(typeArg, targetType);
            }
        }
        return resolvedArgs;
    }
    // If the type is not parameterized, return null
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the type parameters for the target type
    Type[] typeParameters = ((ParameterizedType) targetType).getActualTypeArguments();

    // Get the raw type for the generic type
    Class<?> rawType = (Class<?>) ((ParameterizedType) genericType).getRawType();

    // Create a map of type variables to actual types
    Map<TypeVariable<?>, Class<?>> typeVariableMap = new HashMap<>();
    for (Type type : typeParameters) {
        if (type instanceof Class<?>) {
            typeVariableMap.put(((Class<?>) type).getTypeParameters()[0], (Class<?>) type);
        } else if (type instanceof TypeVariable) {
            typeVariableMap.put((TypeVariable<?>) type, targetType);
        }
    }

    // Resolve the type arguments for the generic type
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
    for (int i = 0; i < typeArguments.length; i++) {
        if (typeArguments[i] instanceof TypeVariable) {
            typeArguments[i] = typeVariableMap.get((TypeVariable<?>) typeArguments[i]);
        }
    }

    // Return the resolved type arguments
    return Arrays.stream(typeArguments).map(a -> (Class<?>) a).toArray(Class[]::new);
}

