private void addToCache(METRICS data) {
    // Check if the data is null
    if (data == null) {
        throw new IllegalArgumentException("Data cannot be null");
    }

    // Get the current value in the cache
    METRICS currentValue = cache.get(data.getKey());

    // If there is no current value in the cache, simply add the new data
    if (currentValue == null) {
        cache.put(data.getKey(), data);
        return;
    }

    // If there is a current value, merge the new data with the existing value
    METRICS mergedValue = merge(currentValue, data.getValue());
    cache.put(data.getKey(), mergedValue);
}

private METRICS merge(METRICS first, METRICS second) {
    // If both the first and second metrics are null, return null
    if (first == null && second == null) {
        return null;
    }

    // If only the first metrics is null, return the second metrics
    if (first == null) {
        return second;
    }

    // If only the second metrics is null, return the first metrics
    if (second == null) {
        return first;
    }

    // Merge the two metrics objects
    METRICS result = new METRICS();
    result.setValue(first.getValue() + second.getValue());
    result.setCount(first.getCount() + second.getCount());
    return result;
}

