public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null || mappings.getProperties() == null) {
        throw new IllegalArgumentException("Invalid input mappings");
    }

    // Get fields that not exist in the input mappings
    Set<String> missingFields = new HashSet<>();
    for (String field : getFieldNames(tableName)) {
        if (!mappings.getProperties().containsKey(field)) {
            missingFields.add(field);
        }
    }

    // Return mappings with the missing fields
    Mappings diffMappings = new Mappings();
    diffMappings.put("properties", new LinkedHashMap<>());
    for (String field : missingFields) {
        diffMappings.getProperties().put(field, getMappingFromField(tableName, field));
    }
    return diffMappings;
}

private Set<String> getFieldNames(String tableName) {
    Set<String> fieldNames = new HashSet<>();
    try {
        List<String> columns = JdbcUtils.getColumnNames(tableName);
        for (String field : columns) {
            fieldNames.add(field);
        }
    } catch (SQLException e) {
        throw new RuntimeException("Failed to get field names from table " + tableName, e);
    }
    return fieldNames;
}

private Map<String, Object> getMappingFromField(String tableName, String field) {
    Map<String, Object> mapping = new LinkedHashMap<>();
    if (getFieldType(tableName, field) == FieldType.numeric) {
        mapping.put("type", "long");
        mapping.put("doc_values", true);
    } else if (getFieldType(tableName, field) == FieldType.string) {
        mapping.put("type", "keyword");
        mapping.put("index", false);
    } else {
        throw new IllegalArgumentException("Unsupported field type " + getFieldType(tableName, field));
    }
    return mapping;
}

