    // Get the table metadata for the input mappings
    TableMetadata tableMetadata = ElasticService.getTableMetadata(tableName);

    // Iterate over the table metadata fields and add fields that do not exist in the input mappings
    for (FieldMetadata fieldMetadata : tableMetadata.getFields()) {
        if (!inputFieldNames.contains(fieldMetadata.getFieldName())) {
