    if (indexMetadata != null) {
        Map<String, MappingMetadata> mappingMetadataMap = indexMetadata.getMapping(). mappings();
        if (!mappingMetadataMap.isEmpty()) {
            MappingMetadata mappingMetadata = mappingMetadataMap.values().iterator().next();
            if (mappingMetadata != null) {
                Map<String, Object> mappingSource = mappingMetadata.getSourceAsMap();
                if (mappingSource != null) {
                    Map<String, Object> properties = (Map<String, Object>) mappingSource.get("properties");
                    if (properties != null) {
                        properties.forEach((k, v) -> {
                            if (!columnNames.contains(k) && !((Map<String, Object>) v).containsKey("enabled") && ((Map<String, Object>) v).get("enabled").equals("false")) {
                                diff.put(k, v);
                            }
                        });
                    }
                }
            }
        }
    }
    return diff;
}

