public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 60 * 60 * 1000; // 1 hour in milliseconds

    long startTime = start / fetchDataDuration * fetchDataDuration;
    long endTime = end / fetchDataDuration * fetchDataDuration;

    while (startTime < endTime) {
        long timeRangeStart = startTime;
        long timeRangeEnd = startTime + fetchDataDuration;

        if (timeRangeEnd > endTime) {
            timeRangeEnd = endTime;
        }

        timeRanges.add(new TimeRange(timeRangeStart, timeRangeEnd));

        startTime += fetchDataDuration;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    // Calculate the maximum number of time ranges that can be generated
    int maxRanges = (int) (end - start) / duration;

    // Generate the time ranges
    for (int i = 0; i < maxRanges; i++) {
        long startTime = start + i * duration;
        long endTime = startTime + duration;
        if (endTime > end) {
            endTime = end;
        }
        timeRanges.add(new TimeRange(startTime, endTime));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    while (start < end) {
        if (start + FETCH_DATA_DURATION > end) {
            timeRanges.add(new TimeRange(start, end));
            break;
        }
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION));
        start += FETCH_DATA_DURATION;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = FETCH_DATA_DURATION;
    List<TimeRange> timeRanges = new ArrayList<>();

    long startTime = start;
    while (startTime < end) {
        long endTime = Math.min(startTime + duration, end);
        timeRanges.add(new TimeRange(startTime, endTime));
        startTime = endTime;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        TimeRange timeRange = new TimeRange(currentStart, currentEnd);
        timeRanges.add(timeRange);
        currentStart = currentEnd;
    }
    return timeRanges;
}

