    // Get the year, month, and day from the time bucket
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket / 1000000) % 100);
    int day = (int) (timeBucket % 1000000);

    // Add the dayStep to the day
    day += dayStep;

    // Check if the day is greater than 28, if so, increment the month and set the day to 1
    if (day > 28) {
        month++;
        day = 1;
    }

    // Check if the month is greater than 12, if so, increment the year and set the month to 1
    if (month > 12) {
        year++;
        month = 1;
    }

    // Return the re-formatted time bucket
    return (long) (year * 100000000 + month * 1000000 + day);
}

