public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else if (c < 0xd800 || c > 0xdfff) {
            size += 3;
        } else {
            i++;
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final String str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(c)) {
            i++;
            size += 4;
        } else {
            size += 3;
        }
    }
    return size;
}

