public static int computeUTF8Size(CharSequence str, int index, int length) throws RuntimeException {
    if (str == null) {
        throw new NullPointerException("str is null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("index is out of bounds: " + index);
    }
    if (length < 0) {
        throw new IllegalArgumentException("length is negative: " + length);
    }
    int codePoint;
    int offset = index;
    int size = 0;
    for (int i = index; i < index + length && i <= str.length(); i++) {
        codePoint = str.codePointAt(i);
        if (codePoint < 0x80) {  // 1-byte
            size++;
        } else if (codePoint < 0x800) {  // 2-byte
            size += 2;
        } else if (codePoint < 0xd800 || codePoint > 0xdfff) {  // 3-byte
            size += 3;
        } else { // 4-byte
            throw new RuntimeException("Invalid UTF-8 sequence: " + codePoint);
        }
    }
    return size;
}

public static int computeUTF8Size(String str, int index, int length) {
    int i = index;
    int result = 0;
    for (int len = length; len > 0; i++) {
        char c = str.charAt(i);
        if (c >= 1 && c <= 127) {
            result++;
        } else if (c >= 128 && c <= 2047) {
            result += 2;
        } else {
            result += 3;
        }
        len--;
    }
    return result;
}

