    int suffixLength = suffix.length();
    if (suffixLength > strLength) {
        return false;
    }
    int start = strLength - suffixLength;
    int i = start;
    for (int j = 0; j < suffixLength; j++) {
        if (ignoreCase) {
            if (Character.toLowerCase(str.charAt(i++)) != Character.toLowerCase(suffix.charAt(j))) {
                i -= j;
                return false;
            }
        } else {
            if (str.charAt(i++) != suffix.charAt(j)) {
                i -= j;
                return false;
            }
        }
    }
    return true;
}

