public long readRawVarint64() throws IOException {
    byte tmp = readRawByte();

    if (tmp >= 0) {
        return tmp;
    }

    // Optimize for one-byte and two-byte cases, which are the most common.
    int result = tmp & 0x7f;
    if ((tmp = readRawByte()) >= 0) {
        result |= tmp << 7;
    } else {
        // Shift for the remaining 21 bytes
        int shift = 14;
        while (shift >= 0) {
            if ((tmp = readRawByte()) >= 0) {
                result |= (tmp & 0x7f) << shift;
                break;
            }
            shift -= 7;
        }

        if (shift < 0) {
            // If we had to shift 32 bits with no 
            // result, the stream has too many bytes.
            throw new IOException("Malformed Varint");
        }
    }

    return result;
}

private long readRawVarint64() {
  int shift = 0;
  long result = 0;
  while (shift < 64) {
    final int b = inputStream.read();
    if (b == -1) {
      throw new EOFException("End of input reached");
    }
    result |= (long) (b & 0x7F) << shift;
    if ((b & 0x80) == 0) {
      return result;
    }
    shift += 7;
  }
  throw new IOException("Varint is too long");
}

