public void pop(String descriptor) {
    // Check if the descriptor is a type descriptor
    if (descriptor.charAt(0) == 'L') {
        // Pop the corresponding type
        Class<?> type = Type.getType(descriptor).getClassName();
        pop(type);
    } else {
        // Pop the argument types of the corresponding method
