private void pop(String descriptor) {
    if (descriptor.startsWith("(")) {
        // the descriptor refers to a method type, so pop the argument types
        final Type[] argumentTypes = Type.getArgumentTypes(descriptor);
        for (int i = 0; i < argumentTypes.length; i++) {
            pop(argumentTypes[i]);
        }
    } else {
        // the descriptor refers to a primitive type, so pop the corresponding value
        switch (descriptor) {
            case "Z": // boolean
                pop(ValueType.BOOLEAN);
                break;
            case "C": // char
                pop(ValueType.CHAR);
                break;
            case "B": // byte
                pop(ValueType.BYTE);
                break;
            case "S": // short
                pop(ValueType.SHORT);
                break;
            case "I": // int
                pop(ValueType.INT);
                break;
            case "J": // long
                pop(ValueType.LONG);
                break;
            case "F": // float
                pop(ValueType.FLOAT);
                break;
            case "D": // double
                pop(ValueType.DOUBLE);
                break;
            default:
                throw new IllegalArgumentException("Unsupported descriptor: " + descriptor);
        }
    }
}

void pop(String descriptor) {
    int count = 0;
    while (count < descriptor.length()) {
        // Check if the current character is a primitive type descriptor
        if (descriptor.charAt(count) == 'Z' || descriptor.charAt(count) == 'B' || descriptor.charAt(count) == 'S' || descriptor.charAt(count) == 'C' || descriptor.charAt(count) == 'I' || descriptor.charAt(count) == 'F' || descriptor.charAt(count) == 'J' || descriptor.charAt(count) == 'D') {
            // Pop a primitive type from the output frame stack
            outputFrameStack.pop();
            count++;
        } else if (descriptor.charAt(count) == 'L') {
            // Pop a reference type from the output frame stack
            outputFrameStack.pop(descriptor.substring(count + 1).replace('/', '.'));
            count = descriptor.indexOf(';');
        } else if (descriptor.charAt(count) == '[') {
            // Pop an array type from the output frame stack
            outputFrameStack.pop(descriptor.substring(count));
        } else {
            // Method descriptor, pop the argument types described by the descriptor
            String[] argTypes = descriptor.substring(count + 1).split(";");
            for (String argType : argTypes) {
                pop(argType);
            }
            count = descriptor.length();
        }
    }
}

