    Box2D box1 = new Box2D(new Vector2(box.min.x, box.min.y), new Vector2(centerX, box.max.y));
    Box2D box2 = new Box2D(new Vector2(centerX, box.min.y), new Vector2(box.max.x, box.max.y));

