    if (box == null || box.getWidth() == 0) {
        throw new IllegalArgumentException("Invalid box parameter");
    }

    double midX = box.getMinX() + (box.getWidth() / 2);

    return new Pair<Box2D, Box2D>(new Box2D(box.getMinX(), midX),
        new Box2D(midX, box.getMaxX()));
