public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Check if the box is valid and has non-zero width
    if (box == null || box.width == 0) {
        throw new IllegalArgumentException("Invalid box or zero width");
    }

    // Calculate the new width for each half box
    double newWidth = box.width / 2.0;

    // Calculate the half box positions
    double halfXMin = box.xMin + newWidth;
    double halfXMax = box.xMax - newWidth;

    // Create the two new box objects
    Box2D halfBox1 = new Box2D(box.xMin, box.yMin, halfXMin, box.yMax);
    Box2D halfBox2 = new Box2D(halfXMin, box.yMin, box.xMax, box.yMax);

    // Return the pair of half boxes
    return new Pair<Box2D, Box2D>(halfBox1, halfBox2);
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    float midX = box.getX() + box.getWidth() / 2f;
    Box2D leftBox = new Box2D(box.getX(), box.getY(), midX - box.getX(), box.getHeight());
    Box2D rightBox = new Box2D(midX, box.getY(), box.getX() + box.getWidth() - midX, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

