double centerX = box.getX() + box.getWidth() / 2;

// Calculate the half-width of the resulting boxes
double halfWidth = box.getWidth() / 2;

// Create the first resulting box
Box2D firstBox = new Box2D(box.getX(), box.getY(), halfWidth, box.getHeight());

