    if (node == null) {
        throw new NullPointerException("node cannot be null");
    }

    // Check for null output
    if (out == null) {
        throw new NullPointerException("out cannot be null");
    }

    // Write the contents of the buffer to the output
    int contentSize = 0;
    Node head = node.head;
    while (head != null) {
        out.writeByte((byte) (head.value & 0xFF));
        contentSize++;
        head = head.next;
    }

    // Return the total content size of the buffer
    return contentSize;
}

public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
    // Check for null values
    if (out == null || node == null) {
        throw new NullPointerException("out and node cannot be null");
    }

    // Write the total number of entries in the buffer
    int numEntries = node.size();
    out.writeInt(numEntries);

    // Write each entry in the buffer
    for (int i = 0; i < numEntries; i++) {
        // Write the entry index
        out.writeInt(i);

        // Write the entry data
        out.write(node.get(i));
    }

    // Return the total content size of the buffer
    return numEntries * (Integer.SIZE / Byte.SIZE) + node.getTotalSize();
}

