    // Format the message based on the event type
    String message = null;
    switch (event.getEventType()) {
        case INFO:
            message = formatInfoMessage(event);
            break;
        case WARNING:
            message = formatWarningMessage(event);
            break;
        case ERROR:
            message = formatErrorMessage(event);
            break;
        default:
            message = formatDefaultMessage(event);
    }
    return message;
}

