private void putAbstractTypes(final int start, final int end) {
    if (start > end) {
        throw new IllegalArgumentException("Start index should be less than end index");
    }
    if (start < 0 || end > currentFrame.length) {
        throw new ArrayIndexOutOfBoundsException("Index out of bounds: " + start + ".." + end);
    }
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        if (type < 4) {
            stackMapTableEntries.put(type, 0);
        } else {
            stackMapTableEntries.put(type, currentFrame.length);
        }
    }
}

public void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        VerificationTypeInfo info = null;
        switch (currentFrame.getStack(i)) {
            case Integer:
            case Float:
                info = new IntegerVerificationTypeInfo();
                break;
            case Long:
            case Double:
                info = new LongVerificationTypeInfo();
                break;
            case Object:
                info = new ObjectVerificationTypeInfo();
                break;
            default:
                throw new IllegalArgumentException("Unknown type in stack frame: " + currentFrame.getStack(i));
        }
        stackMapTableEntries.add(info);
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        final Object type = currentFrame.get(i);
        if (type instanceof Integer) {
            stackMapTableEntries.add(new StackMapTableEntryInteger());
        } else if (type instanceof Float) {
            stackMapTableEntries.add(new StackMapTableEntryFloat());
        } else if (type instanceof Long) {
            stackMapTableEntries.add(new StackMapTableEntryLong());
        } else if (type instanceof Double) {
            stackMapTableEntries.add(new StackMapTableEntryDouble());
        } else {
            throw new IllegalArgumentException("Invalid type: " + type);
        }
    }
}

private void putAbstractTypes(int start, int end) {
for (int i = start; i < end; i++) {
if (currentFrame[i] == NULL_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Null));
} else if (currentFrame[i] == INTEGER_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Integer));
} else if (currentFrame[i] == FLOAT_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Float));
} else if (currentFrame[i] == LONG_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Long));
} else if (currentFrame[i] == DOUBLE_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Double));
} else if (currentFrame[i] == OBJECT_TYPE) {
stackMapTableEntries.add(new VerificationTypeInfo(VerificationTypeInfo.ITEM_Object, currentFrame[i]));
}
}
}

void putAbstractTypes(int start, int end) {
    // Check if the start and end indices are valid
    if (start < 0 || start >= end || end > currentFrame.length) {
        throw new IllegalArgumentException("Invalid start or end index");
    }

    // Loop through the types in the current frame
    for (int i = start; i < end; i++) {
        // Get the type of the current frame entry
        VerificationTypeInfo type = currentFrame[i].getVerificationTypeInfo();

        // Check if the type is an abstract type
        if (type.isAbstract()) {
            // Put the abstract type in the stack map table
            stackMapTableEntries.put(type);
        } else {
            // Put the non-abstract type in the stack map table
            stackMapTableEntries.put(new JVMSVerificationTypeInfo(type.getTag(), null));
        }
    }
}

