private static Character convertToChar(Class<?> type, Object value) throws Exception {

    if (!type.equals(Character.class)) {
      throw new Exception("Invalid conversion from " + value.getClass().getName() + " to Character");
    }

    if (value == null) {
      return null;
    }

    if (value instanceof Character) {
      return (Character) value;
    }

    if (value instanceof String) {
      String str = (String) value;
      if (str.length() != 1) {
        throw new Exception("Cannot convert String of length " + str.length() + " to Character");
      }
      return str.charAt(0);
    }

    if (value instanceof Number) {
      return (char) ((Number) value).intValue();
    }

    throw new Exception("Cannot convert " + value.getClass().getName() + " to Character");
  }

