}

public Character convertToCharacter(Class<?> type, Object value) throws Exception {

  if (type.equals(Character.class)) {
    if (value instanceof Character) {
      return (Character) value;
    } else if (value instanceof String) {
      return Character.valueOf(((String) value).charAt(0));
    } else if (value instanceof Number) {
      return (char) ((Number) value).intValue();
    } else {
      throw new IllegalArgumentException("Cannot convert value of type " + type.getName() + " to Character");
    }
  } else if (type.equals(String.class)) {
    if (value instanceof Character) {
      return value.toString();
    } else if (value instanceof String) {
      return (String) value;
    } else if (value instanceof Number) {
      return String.valueOf(((Number) value).intValue());
    } else {
      throw new IllegalArgumentException("Cannot convert value of type " + type.getName() + " to String");
    }
  } else if (type.equals(Number.class)) {
    if (value instanceof Character) {
      return ((Character) value).charValue();
    } else if (value instanceof String) {
      return Integer.valueOf(((String) value).charAt(0));
    } else if (value instanceof Number) {
      return (Number) value;
    } else {
      throw new IllegalArgumentException("Cannot convert value of type " + type.getName() + " to Number");
    }
  } else {
    throw new IllegalArgumentException("Cannot convert value of type " + type.getName() + " to Character");
  }
}

@Override
protected Character convertToType(final Object value) throws Exception {
    if (value instanceof Character) {
        return (Character) value;
    } else if (value instanceof Boolean) {
        return (Boolean) value ? 'T' : 'F';
    } else if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    } else if (value instanceof String) {
        final String str = (String) value;
        if (str.length() != 1) {
            throw new Exception("Cannot convert value to a character: string has more than one character");
        }
        return str.charAt(0);
    }
    throw new Exception("Cannot convert value to a character: unsupported type");
}

