public static int nextPrime(int desiredCapacity) {
    // Check if the input is a valid prime number
    if (desiredCapacity < 2 || !isPrime(desiredCapacity)) {
        throw new IllegalArgumentException("Invalid input: " + desiredCapacity + " is not a prime number.");
    }

    // Start with the next prime number after the input
    int prime = nextPrime(desiredCapacity + 1);

    // Adjust the prime number if necessary
    if (prime - desiredCapacity > 11 && prime - desiredCapacity < 101) {
        prime -= 1;
    }

    return prime;
}

private static boolean isPrime(int n) {
    // Base case: n is 2 or a prime number
    if (n == 2 || n % 2 == 0) {
        return true;
    }

    // Check if n is odd and has no factors other than 1 and itself
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}

static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1000) {
        return (int) (desiredCapacity * (1 + 0.11));
    } else {
        return (int) (desiredCapacity * (1 + 0.1));
    }
}

public static int nextPrime(int desiredCapacity) {
    // Check for invalid input
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("Invalid input: desiredCapacity cannot be negative");
    }

    // Find the next prime number that is greater than or equal to the desired capacity
    int prime = 2;
    while (prime < desiredCapacity) {
        prime++;
        if (isPrime(prime)) {
            return prime;
        }
    }

    // If the desired capacity is greater than or equal to 1000 and within 11% of a multiple of 1000, return the next multiple of 1000
    if (desiredCapacity >= 1000 && prime - desiredCapacity <= 0.11 * desiredCapacity) {
        return prime - (prime - desiredCapacity) % 1000;
    }

    // Otherwise, return the nearest prime number to the desired capacity
    return prime;
}

private static boolean isPrime(int n) {
    // Check if n is a power of 2
    if ((n & (n - 1)) == 0) {
        return false;
    }

    // Check if n is divisible by any prime less than or equal to sqrt(n)
    int sqrtN = (int)Math.sqrt(n);
    for (int i = 2; i <= sqrtN; i++) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }

    int prime = 0;
    boolean found = false;
    for (int i = 1; i < desiredCapacity; i++) {
        if (isPrime(i)) {
            prime = i;
            found = true;
            break;
        }
    }

    if (!found) {
        throw new IllegalStateException("no prime found for desiredCapacity");
    }

    if (prime < desiredCapacity) {
        prime++;
    }

    return prime;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n == 2) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity >= 1000) {
        // Handle large capacities more efficiently
        return (int) (1.1 * desiredCapacity);
    } else {
        // Handle small capacities more efficiently
        return Math.max(11, desiredCapacity);
    }
}

