String trimTrailingWhitespace(String str) {
    int length = str.length();
    int lastNonWhitespace = -1;
    for (int i = length - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhitespace = i;
            break;
        }
    }
    if (lastNonWhitespace == -1) {
        return "";
    }
    return str.substring(0, lastNonWhitespace + 1);
}

public static String trimTrailingWhitespace(String str) {
    // check if the string is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    // find the last index of a non-whitespace character
    int lastNonWhiteIdx = str.length() - 1;
    for (int i = lastNonWhiteIdx; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhiteIdx = i;
            break;
        }
    }

    // return the substring from the first non-whitespace character to the end
    return str.substring(0, lastNonWhiteIdx + 1);
}

public static String trimTrailingWhitespace(String str) {
    int length = str.length();
    while (length > 0 && Character.isWhitespace(str.charAt(length - 1))) {
        length--;
    }
    return str.substring(0, length);
}

public static String trimTrailingWhitespace(String str) {
    // Check for null or empty string
    if (str == null || str.isEmpty()) {
        return str;
    }

    // Trim trailing whitespace characters
    int end = str.length() - 1;
    while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
        end--;
    }

    return str.substring(0, end + 1);
}

public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int length = str.length();
    while (length > 0 && Character.isWhitespace(str.charAt(length - 1))) {
        length--;
    }
    return str.substring(0, length);
}

