@Override
public String readString() throws IOException {
    try {
        int c = in.read();
        while (c == '\\') {
            c = in.read();
        }
        if (c == 'n') {
            return null;
        }
        if (c < 0) {
            throw new EOFException();
        }
        if (c > 127) {
            throw new UTFDataFormatException();
        }
        char[] chars = new char[64];
        int pos = 0;
        while (true) {
            if (c == '\\') {
                c = in.read();
                switch (c) {
                    case '\\':
                        chars[pos++] = '\\';
                        break;
                    case 'n':
                        chars[pos++] = '\n';
                        break;
                    case 't':
                        chars[pos++] = '\t';
                        break;
                    case 'r':
                        chars[pos++] = '\r';
                        break;
                    case 'f':
                        chars[pos++] = '\f';
                        break;
                    case '\'':
                        chars[pos++] = '\'';
                        break;
                    case '"':
                        chars[pos++] = '\"';
                        break;
                    default:
                        throw new UTFDataFormatException();
                }
            } else {
                chars[pos++] = (char) c;
            }
            if (pos == 64) {
                String str = new String(chars);
                pos = 0;
                chars = new char[64];
                return str;
            }
            c = in.read();
        }
    } catch (IOException e) {
        throw new RuntimeException("Error reading string", e);
    }
    String str = new String(chars, 0, pos);
    pos = 0;
    chars = new char[64];
    return str;
}

