public String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
	// check if the constant pool entry index is valid
	if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
		throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
	}

	// read the length of the string
	int stringLen = (classFileBuffer[constantPoolEntryIndex] & 0xFF) << 8 | (classFileBuffer[constantPoolEntryIndex + 1] & 0xFF);

	// check if the string length is valid
	if (stringLen < 0) {
		throw new IllegalStateException("Invalid string length: " + stringLen);
	}

	// check if the charBuffer is valid
	if (charBuffer.length < stringLen) {
		throw new IllegalArgumentException("Insufficient capacity of the charBuffer: " + charBuffer.length + " < " + stringLen);
	}

	// read the string
	for (int i = 0; i < stringLen; i++) {
		charBuffer[i] = (char) (classFileBuffer[constantPoolEntryIndex + 2 + i] & 0xFF);
	}

	return new String(charBuffer, 0, stringLen);
}

public final String readUtf(int constantPoolEntryIndex,char[] charBuffer) {
    ByteBuffer buffer = this.classFileBuffer.slice();
    // Skip the tag byte (1 byte)
    int minCapacity = constantPoolEntryIndex;
    int tag = buffer.get(minCapacity);
    switch (tag) {
    case ConstantPoolEntryTag.CONSTANT_Utf8:
        // Skip the tag byte
        buffer = buffer.position(minCapacity + 1);
    }
    int length = buffer.getShort();
    if (charBuffer.length < length) {
        throw new InvalidConstantPoolEntryException("The specified constant pool entry has a length that exceeds the size of the provided char buffer");
    }
    String value = new String(buffer.array(), minCapacity + 1, length, StandardCharsets.UTF_8);
    return value;
}

public String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) throws IOException{
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.getInt(constantPoolEndIndex)){
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    // Read the length of the string
    int length = classFileBuffer.getInt(constantPoolEndIndex + constantPoolEntryIndex * 2);
    if (length < 0 || length > charBuffer.length){
        throw new IllegalArgumentException("Invalid length for string");
    }
    // Read the string data
    classFileBuffer.position(constantPoolEndIndex + constantPoolEntryIndex * 2 + 2);
    classFileBuffer.get(charBuffer, 0, length);
    return new String(charBuffer, 0, length);
}

