final String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    // Validate the input parameters
    if (constantPoolEntryIndex < 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex cannot be negative");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer cannot be null");
    }

    // Read the entry from the constant pool
    int entryOffset = classFileBuffer.getInt(constantPoolEntryIndex);
    int entryLength = classFileBuffer.getShort(entryOffset + 1);

    // Validate the entry offset and length
    if (entryOffset < 0) {
        throw new IllegalStateException("invalid entry offset: " + entryOffset);
    }
    if (entryLength < 0) {
        throw new IllegalStateException("invalid entry length: " + entryLength);
    }
    if (entryOffset + entryLength >= charBuffer.length) {
        throw new IllegalStateException("entry exceeds buffer size");
    }

    // Read the entry data and convert it to a String
    int i = 0;
    while (i < entryLength) {
        charBuffer[i] = (char) classFileBuffer.getUByte(entryOffset + 2 + i);
        i++;
    }
    return new String(charBuffer, 0, i);
