public static OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // We use a circulator to iterate over the component
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // We use a stack to keep track of the nodes we have visited
    // and to keep track of the direction we need to move in
    Stack<Pair<Node, Integer>> stack = new Stack<>();

    // We start at the starting node and move in the given direction
    stack.push(Pair.of(start, dir));

    while (!stack.isEmpty()) {
        // We pop the current node and direction from the stack
        Pair<Node, Integer> current = stack.pop();
        Node node = current.getKey();
        int direction = current.getValue();

        // We check if the node satisfies the predicate
        if (predicate.test(node)) {
            // If the node satisfies the predicate, we return a circulator to it
            return new OuterFaceCirculator(node, direction);
        }

        // We check if we have reached the stop node
        if (node == stop) {
            // If we have, we return a circulator to it
            return new OuterFaceCirculator(stop, direction);
        }

        // We add the neighbor nodes in the opposite direction to the stack
        for (int i = 0; i < 4; i++) {
            // If the direction is clockwise, we move in the counterclockwise direction
            int newDirection = direction == OuterFaceCirculator.CLOCKWISE ? OuterFaceCirculator.COUNTERCLOCKWISE : OuterFaceCirculator.CLOCKWISE;
            Node neighbor = node.getNeighbor(newDirection);
            if (neighbor != null) {
                stack.push(Pair.of(neighbor, newDirection));
            }
        }
    }

    // If we reach this point, we did not find a node that satisfies the predicate
    // or we reached the stop node, so we return the circulator

void selectOnOuterFace(Predicate<Node> predicate,Node start,Node stop,int dir){
    OuterFaceCirculator cir = new OuterFaceCirculator(start, dir);
    while(cir.hasNext() && cir.next() != stop){
        if(predicate.test(cir.get())){
            return cir;
        }
    }
    return null;
}

