}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // check if the start node satisfies the predicate
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, stop, dir);
    }

    // check if the stop node satisfies the predicate
    if (predicate.test(stop)) {
        return new OuterFaceCirculator(stop, start, -dir);
    }

    // search for the first node on the outer face that satisfies the predicate
    for (int i = 0; i < 2; i++) {
        Node current = start;
        do {
            current = current.nextOnFace(dir);
            if (predicate.test(current)) {
                return new OuterFaceCirculator(current, stop, dir);
            }
        } while (current != start);
    }

    // no node on the outer face satisfies the predicate, return a circulator to the stop node
    return new OuterFaceCirculator(stop, start, -dir);
}

