private boolean isShardingKeyIndicesContinuous(Set<Integer> shardingKeyIndices) {
    // Check if the sharding key indices are continuous
    List<Integer> sortedIndices = new ArrayList<>(shardingKeyIndices);
    sortedIndices.sort(Comparator.naturalOrder());
    int prevIndex = -1;
    for (Integer index : sortedIndices) {
        if (prevIndex + 1 != index) {
            return false;
        }
        prevIndex = index;
    }
    return true;
}

