public byte[] toByteArray() {
    byte[] bytes = new byte[length()];
    int index = 0;
    while (index < length()) {
        char c = charAt(index);
        if (c < 128) {
            bytes[index] = (byte) c;
        } else if (c < 2048) {
            bytes[index] = (byte)(0xc0 | (c >> 6));
            index++;
            bytes[index] = (byte)(0x80 | (c & 0x3f));
        } else {
            bytes[index] = (byte)(0xe0 | (c >> 12));
            index++;
            bytes[index] = (byte)(0x80 | ((c >> 6) & 0x3f));
            index++;
            bytes[index] = (byte)(0x80 | (c & 0x3f));
        }
        index++;
    }
    return bytes;
}

EdgeSetToTourMethod (EdgeSet, Graph) {

    // Validate input
    if (tour == null || tour.isEmpty ())
        throw new IllegalArgumentException ("Tour set cannot be null or empty");
    if (graph == null)
        throw new IllegalArgumentException ("Graph cannot be null");

    // Initialize graph path
    GraphPath<V,E> path = new GraphPath<V,E> ();
    path.setGraph (graph);

    // Iterate over tour set
    for (E edge : tour) {

        // Get start and end vertices of edge
        V startVertex = graph.getStartVertex (edge);
        V endVertex = graph.getEndVertex (edge);

        // Add edge to path
        path.addEdge (edge);

        // Set start vertex of next edge
        path.setStartVertex (endVertex);

    }

    // Set end vertex of final edge
    path.setEndVertex (graph.getEndVertex (path.getEdges ().get (path.getLength () - 1)));

    // Return graph path
    return path;

}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null || graph.getEdgeCount() == 0) {
        throw new IllegalArgumentException("Invalid input: tour or graph is null or empty.");
    }

    List<E> edges = new ArrayList<>(tour);
    V startVertex = null;
    V endVertex = null;
    for (E edge : edges) {
        startVertex = graph.getEdgeSource(edge);
        endVertex = graph.getEdgeTarget(edge);
        if (startVertex == endVertex) {
            throw new IllegalArgumentException("Invalid input: tour contains self-loops.");
        }
    }

    if (startVertex == null || endVertex == null) {
        throw new IllegalArgumentException("Invalid input: tour does not contain any edges");
    }

    // Build the graph path
    GraphPath<V, E> path = new GraphPath<>(startVertex, endVertex, graph);
    for (int i = 0; i < edges.size(); i++) {
        E edge = edges.get(i);
        path.addEdge(edge);
        if (i != edges.size() - 1) {
            V nextVertex = graph.getEdgeTarget(edge);
            path.addVertex(nextVertex);
        }
    }
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Handle invalid input
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Get the start node of the tour
    V startNode = graph.getNode(0);

    // Initialize the graph path
    GraphPath<V, E> tourPath = new GraphPath<>(startNode, graph);

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the nodes connected by the edge
        V node1 = edge.getNode1();
        V node2 = edge.getNode2();

        // Add the edge to the graph path
        tourPath.addEdge(node1, node2);
    }

    // Return the completed graph path
    return tourPath;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Check if the input is valid
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Null input: tour and/or graph must not be null");
    }

    // Create a GraphPath object
    GraphPath<V, E> graphPath = new GraphPath<>(graph);

    // Loop through the set of edges and add them to the GraphPath
    for (E edge : tour) {
        if (!graph.containsEdge(edge) || !graph.areAdjacent(edge.getStart(), edge.getEnd())) {
            throw new IllegalArgumentException("Invalid edge: edge must be a member of the graph and adjacent to the end vertices");
        }
        graphPath.addEdge(edge);
    }

    // Return the completed graph path
    return graphPath;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path
    GraphPath<V, E> tourPath = new GraphPath<V, E>();

    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the source and target vertices of the edge
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Add the edge to the graph path
        tourPath.addEdge(source, target, edge);
    }

    // Return the graph path
    return tourPath;
}

