public Symbol addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (Symbol symbol : constantPool) {
        if (symbol.getType() == Symbol.Type.CONSTANT_NameAndType && symbol.getName().equals(name) && symbol.getDescriptor().equals(descriptor)) {
            // If a similar item is found, return it
            return symbol;
        }
    }

    // If a similar item is not found, create a new one
    Symbol symbol = new Symbol(Symbol.Type.CONSTANT_NameAndType, name, descriptor);
    constantPool.add(symbol);
    return symbol;
}

public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 0; i < constantPoolSize; i++) {
        if (constantPool[i] instanceof CONSTANT_NameAndType_info) {
            CONSTANT_NameAndType_info existing = (CONSTANT_NameAndType_info) constantPool[i];
            if (existing.getName(this).equals(name) && existing.getDescriptor(this).equals(descriptor)) {
                return i;
            }
        }
    }

    // Create a new CONSTANT_NameAndType_info item and add it to the constant pool
    CONSTANT_NameAndType_info newItem = new CONSTANT_NameAndType_info();
    newItem.setNameIndex(this, addConstantUtf8(name));
    newItem.setDescriptorIndex(this, addConstantUtf8(descriptor));
    constantPoolSize++;
    constantPool = Arrays.copyOf(constantPool, constantPoolSize);
    constantPool[constantPoolSize - 1] = newItem;

    return constantPoolSize - 1;
}

