    // check if the constant pool already contains a similar item
    if(constantPool.contains(name, descriptor)){
        return;
    }

    // add a new CONSTANT_NameAndType_info to the constant pool
    int index = constantPool.add(new CONSTANT_NameAndType_info(name, descriptor));

    // add a new Symbol to the symbol table
    Symbol symbol = new Symbol(name, index, descriptor);
    symbolTable.put(name, symbol);
}

