    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantPoolItem item = constantPool.get(i);
        if (item instanceof ConstantNameAndType) {
            ConstantNameAndType constantNameAndType = (ConstantNameAndType) item;
            if (constantNameAndType.getNameIndex() == utf8.add(name) && constantNameAndType.getDescriptorIndex() == utf8.add(descriptor)) {
                return i;
            }
        }
    }

    // If not, create a new one and add it to the constant pool
    final int nameIndex = utf8.add(name);
    final int descriptorIndex = utf8.add(descriptor);
