}

public static String unescapeId(String input) {
    if (input == null) {
      throw new IllegalArgumentException("input cannot be null");
    }

    // handle escaped characters
    StringBuilder sb = new StringBuilder(input.length());
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      if (c == '\\') {
        // check if we have enough characters in the string to unescape
        if (i + 1 == input.length()) {
          throw new IllegalArgumentException("invalid escape sequence at the end of the string");
        }

        char nextChar = input.charAt(i + 1);
        switch (nextChar) {
          case 'n':
            sb.append('\n');
            break;
          case 'r':
            sb.append('\r');
            break;
          case 't':
            sb.append('\t');
            break;
          case '\\':
            sb.append('\\');
            break;
          default:
