    // Move vertices from the bucket with label minLabel to the bucket with label 0
    for (Set<Integer> bucket : bucketsByLabel) {
        if (bucket.stream().anyMatch(n -> labels.get(n) == minLabel)) {
            bucket.removeIf(n -> labels.get(n) == minLabel);
            bucket.addAll(bucket.removeIf(n -> labels.get(n) == 0));
