    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;
    for(int i = bounds.size() - 1; i >= 0; i--){
        sum += bounds.get(i);
        suffixSumList.add((int) sum);
    }
    return new Pair<>(suffixSumList, sum);
}

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Check for invalid input
    if (bounds == null || bounds.size() == 0) {
        throw new IllegalArgumentException("Input list cannot be null or empty");
    }

    // Initialize suffix sum list and running sum
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long runningSum = 0;

    // Compute suffix sum and running sum
    for (int i = bounds.size() - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        suffixSum.add((int) runningSum);
    }

    // Return computed suffix sum and running sum
    return new Pair<>(suffixSum, runningSum);
}

public static Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Check if the input list is empty
    if (bounds.isEmpty()) {
        throw new IllegalArgumentException("The list of bounds must not be empty");
    }

    // Initialize the suffix sum list and the total sum
    List<Integer> suffixSumList = new ArrayList<>();
    long totalSum = 0L;

    // Loop through the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum for the current element
        int suffixSum = 0;
        for (int j = i; j < bounds.size(); j++) {
            suffixSum += bounds.get(j);
        }

        // Add the suffix sum to the total sum and add it to the suffix sum list
        totalSum += suffixSum;
        suffixSumList.add(suffixSum);
    }

    return new Pair<>(suffixSumList, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize sum and suffix sum list
    long sum = 0L;
    List<Integer> suffixSumList = new ArrayList<>();

    // Iterate through the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Add current element to sum and suffix sum list
        sum += bounds.get(i);
        suffixSumList.add((int) sum);
    }

    // Return computed pair of suffix sum list and sum of all elements
    return new Pair<>(suffixSumList, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    // Check if the input list is null or empty
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Invalid input list");
    }

    // Initialize the suffix sum list and the sum of all elements
    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;

    // Iterate over the input list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Sum the current element with the previous element
        sum += bounds.get(i);
        // Add the sum to the suffix sum list
        suffixSumList.add(sum);
    }

    // Return the suffix sum list and the sum of all elements
    return new Pair<>(suffixSumList, sum);
}

