public static final <V> void reverse(V[] arr, int from, int to) {
    // Input validation
    if (arr == null || from < 0 || to < 0 || to < from) {
      throw new IllegalArgumentException("Invalid input array or range");
    }

    // Calculate the subarray length
    int subarrayLength = to - from + 1;

    // Edge case: No need to reverse an empty array
    if (subarrayLength == 0) {
      return;
    }

    // Reverse the subarray
    for (int i = 0; i < subarrayLength / 2; i++) {
      V temp = arr[from + i];
      arr[from + i] = arr[to - i];
      arr[to - i] = temp;
    }
  }

