private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode head = list.getHead();
    ListNode tail = list.getTail();

    // If the list is empty, return immediately
    if (head == null && tail == null) {
        return;
    }

    // Remove the head node from the list
    ListNode temp = head;
    head = head.getNext();
    list.removeListNode(temp);

    // Add each node in the list to this list
    while (head != null) {
        addListNode(head);
        head = head.getNext();
    }

    // Check if the list is the last node in the list
    if (tail == null) {
        return;
    }

    // Add the tail node to the list
    addListNode(tail);
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Check if the provided list is null
    if(list == null){
        throw new NullPointerException("The provided list is null.");
    }

    // Lock both lists to prevent concurrent access
    synchronized(this){
        synchronized(list){
            // Create a temporary variable to store the first node of the list that is being moved
            ListNode<E> tmp = list.head;
            // Iterate over the list and remove each node
            while(tmp != null){
                // Remove the current node from the list
                list.removeListNode(tmp);
                // Add the node to this list
                addListNode(tmp);
                // Move to the next node in the list
                tmp = tmp.next;
            }
        }
    }
}

public static boolean startsWith(String str, String prefix, boolean ignoreCase) {
