    if (str == null || prefix == null) {
        return (str == null && prefix == null);
    }

    // check if the prefix is in the opposite case of the string
    if (ignoreCase) {
        if (str.toLowerCase().startsWith(prefix.toLowerCase())) {
            return true;
        }
    } else {
        // check if the prefix is in the string
        if (str.startsWith(prefix)) {
            return true;
        }
    }

    return false;
}

