public void putAllWriteable(BeanMap map) {
    for (String propertyName : map.getPropertyNames()) {
        if (map.isWritableProperty(propertyName)) {
            put(propertyName, map.get(propertyName));
        }
    }
}

public void putAllWriteable(BeanMap map) {
    for (String key : map.keySet()) {
        try {
            if (map.isWritable(key)) {
                put(key, map.get(key));
            }
        } catch (PropertyReadOnlyException e) {
            // do nothing
        }
    }
}

public void putAllWriteable(BeanMap map) {
    Class<?> clazz = this.getBeanClass();
    for (PropertyDescriptor pd : Introspector.getBeanInfo(clazz).getPropertyDescriptors()) {
        if (pd.isReadOnly() || !pd.isWriteMethodPresent()) {
            continue;
        }
        String propertyName = pd.getName();
        Object value = map.get(propertyName);
        if (value != null) {
            try {
                pd.getWriteMethod().invoke(this, value);
            } catch (Exception e) {
                throw new IllegalArgumentException("Error setting value for property '" + propertyName + "': " + e.getMessage(), e);
            }
        }
    }
}

public void putAllWriteable(BeanMap map) {
