}

public void putAllWriteable(BeanMap map) {
    // validate input
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }

    // loop through all properties in the given BeanMap and add them to this one
    for (String propertyName : map.keySet()) {
        // check if the property is writable
        if (map.isWritable(propertyName)) {
            // add the property to this BeanMap
            put(propertyName, map.get(propertyName));
        }
    }
}

