public static String base64Decode(String s) {
    // Check if the input string is null or empty
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string is null or empty");
    }

    // Add padding characters to the input string if necessary
    if (s.length() % 4 != 0) {
        s = s + "=".repeat((4 - s.length() % 4) % 4);
    }

    // Translate the input string using Base64 characters
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); i += 4) {
        String block = s.substring(i, i + 4);
        int num = Integer.parseInt(block, 2);
        sb.append((char) num);
    }

    return sb.toString();
}

