public static Meteor lookup(HttpServletRequest r) {
	Meteor result = null;
	// attempt to retrieve the required headers
	String headerName = "X-Meteor-Class";
	String meteorClass = r.getHeader(headerName);
	if (meteorClass != null) {
		// parse the header value as an enum
		try {
			MeteorType type = MeteorType.valueOf(meteorClass);
			// create a new instance of the specified type
			result = type.getClazz().getConstructor(HttpServletRequest.class).newInstance(r);
		} catch (Exception e) {
			System.out.println("Invalid header value for " + headerName);
		}
	} else {
		System.out.println("Missing header: " + headerName);
	}
	return result;
}

public static Meteor lookup(HttpServletRequest r) {
    // Check for valid input
    if (r == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Retrieve the relevant headers and parameters
    String header = r.getHeader("X-Meteor-Auth");
    String parameter = r.getParameter("id");

    // Validate the input
    if (header == null || parameter == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Look up the meteor instance in the database
    Meteor meteor = Meteor.findOne(new Document("_id", parameter));

    // Check if the meteor instance exists
    if (meteor == null) {
        return null;
    }

    // Check if the meteor instance matches the authentication header
    if (!header.equals(meteor.getAuthenticationToken())) {
        throw new IllegalArgumentException("Invalid authentication header");
    }

    // Return the meteor instance
    return meteor;
}

public static Meteor lookup(HttpServletRequest r) {
    // Check if the request contains a JSON payload
    if (r.getContentType().contains("application/json")) {
        try {
            // Read the JSON payload from the request
            JSONObject payload = new JSONObject(r.getInputStream());
            // Look for the "name" property in the payload
            String name = payload.getString("name");
            // Use the name to retrieve the corresponding Meteor instance
            for (Meteor meteor : MeteorDB.getInstance().getMeteors()) {
                if (meteor.getName().equals(name)) {
                    return meteor;
                }
            }
        } catch (JSONException e) {
            // Log the exception and return null
            LOG.warn("Failed to parse JSON payload: " + e.getMessage());
            return null;
        } catch (IOException e) {
            // Log the exception and return null
            LOG.warn("Failed to read request input stream: " + e.getMessage());
            return null;
        }
    } else {
        // Request does not contain a JSON payload, return null
        return null;
    }
}

