private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    for (E edge : graph.edgeSet()) {
        List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
        for (Integer vertex : graph.getNeighbors(edge.getFirst())) {
            if (edge.getSecond() != vertex) {
                separatorList.add(new Pair<>(edge.getFirst(), vertex));
            }
        }
        for (Integer vertex : graph.getNeighbors(edge.getSecond())) {
            if (edge.getFirst() != vertex) {
                separatorList.add(new Pair<>(edge.getSecond(), vertex));
            }
        }
        globalSeparatorList.add(new Pair<>(separatorList, edge));
    }

    return globalSeparatorList;
}

private List<Pair<List<Pair<Integer, Integer>>, E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer, Integer>>, E>> separatorList = new LinkedList<>();
    for (E e : graph.edgeSet()) {
        List<Pair<Integer, Integer>> neighbors = getNeighbors(e);
        List<Pair<Integer, Integer>> separator = new LinkedList<>();
        for (int i = 0; i < neighbors.size(); i++) {
            for (int j = i + 1; j < neighbors.size(); j++) {
                if (!neighbors.get(i).getValue().equals(neighbors.get(j).getValue())) {
                    separator.add(new Pair<>(neighbors.get(i).getKey(), neighbors.get(j).getKey()));
                }
            }
        }
        separatorList.add(new Pair<>(separator, e));
    }
    return separatorList;
}

private List<Pair<Integer, Integer>> getNeighbors(E e) {
    List<Pair<Integer, Integer>> neighbors = new LinkedList<>();
    for (int i = 0; i < graph.getNumVertices(); i++) {
        if (graph.containsEdge(i, e.getStart()) || graph.containsEdge(i, e.getEnd())) {
            neighbors.add(new Pair<>(i, e.getOtherDirection(i)));
        }
    }
    return neighbors;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
  List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

  for(E e : graph.edges()){
    List<Pair<Integer,Integer>> separatorList = new ArrayList<>();

    for(Pair<Integer,Integer> uv : graph.neighborhood(e)){
      List<Pair<Pair<Integer,Integer>,E>> separators = computeSeparators(uv);
      separatorList.addAll(separators);
    }

    globalSeparatorList.add(new Pair<>(separatorList, e));
  }

  return globalSeparatorList;
}

private List<Pair<Integer,Integer>> computeSeparators(Pair<Integer,Integer> uv){
  List<Pair<Integer,Integer>> separators = new ArrayList<>();

  for(E e : graph.edges()){
    if((e.neighbors(uv.first) && e.neighbors(uv.second)) || (!e.neighbors(uv.first) && !e.neighbors(uv.second))){
      continue;
    }

    separators.add(new Pair<>(e.length(), e));
  }

  return separators;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();
    for(E edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> separator = computeLocalSeparator(edge);
        separatorList.add(new Pair<>(separator, edge));
    }
    return separatorList;
}

private List<Pair<Integer,Integer>> computeLocalSeparator(E edge) {
    List<Pair<Integer,Integer>> separator = new ArrayList<>();
    for(Integer vertex : graph.getVertices()) {
        if(graph.isNeighborOf(edge, vertex)) {
            separator.add(new Pair<>(edge, vertex));
        }
    }
    return separator;
}

private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (E e : this.getEdges()) {
        List<Pair<Integer,Integer>> separatorList = new ArrayList<>();
        for (Vertex v : this.getNeighbors(e.getStart())) {
            if (v.equals(e.getEnd())) {
                continue;
            }
            separatorList.add(new Pair<>(new ArrayList<>(Arrays.asList(e.getStart(), e.getEnd())), v));
        }
        globalSeparatorList.add(new Pair<>(separatorList, e));
    }
    return globalSeparatorList;
}

