public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check if the row is valid
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row is not a valid index");
    }

    // Select the row in the table
    table.setRowSelectionInterval(row, row);

    // Scroll the pane to the new row
    Rectangle rect = table.getCellRect(row, 0, true);
    pane.getViewport().setViewPosition(rect.getLocation());

    // Repaint the table to ensure the selected row is properly painted
    table.repaint();
}

selectRow(int row, JTable table, JScrollPane pane) {
    // validate input
    if (row < 0 || row >= table.getRowCount()) {
        throw new IndexOutOfBoundsException("Row index out of bounds");
    }
    // select the row and scroll to it
    table.getSelectionModel().setSelectionInterval(row, row);
    pane.getVerticalScrollBar().setValue(row * table.getRowHeight());
    // repaint the table to update the selection
    table.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Check for invalid inputs
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds");
    }
    if (table != pane.getViewport().getView()) {
        throw new IllegalArgumentException("Table does not belong to the specified JScrollPane");
    }

    // Select the row
    table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
    table.setRowSelectionInterval(row, row);

    // Scroll to the selected row
    Rectangle rect = table.getSelectionModel().getCellRect(row, 0, true);
    pane.getViewport().setViewPosition(new Point(0, rect.y));

    // Repaint the table
    table.repaint();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("SelectRow: invalid arguments");
    }

    table.setRowSelectionInterval(row, row);
    Rectangle rect = table.getCellRect(row, 0, true);
    pane.scrollRectToVisible(rect);
}

public ByteVector putInt(final int intValue){
    final byte[] intBytes = new byte[4];
    for (int i = 0; i < 4; i++) {
        intBytes[i] = (byte) (intValue >>> (24 - i * 8));
    }
    this.addAll(intBytes);
    return this;
}

public byte[] putInt(int intValue){
    // Get the byte array representation of the int
    byte[] intBytes = ByteBuffer.allocate(4).putInt(intValue).array();

    // Enlarge the byte vector if necessary
    if (intBytes.length > value.length - position){
        value = Arrays.copyOf(value, value.length * 2);
    }

    // Copy the int bytes into the byte vector
    System.arraycopy(intBytes, 0, value, position, intBytes.length);
    position += intBytes.length;

    // Return the mutated byte vector
    return value;
}

public ByteVector putInt(int intValue) {
    byte[] bytes = new byte[Integer.BYTES];
    ByteBuffer buffer = ByteBuffer.wrap(bytes);
    buffer.putInt(intValue);
    this.insert(buffer.array());
    return this;
}

public ByteVector putInt(final int intValue) {
    // Check if the ByteVector needs to be enlarged to accommodate the new int
    if (this.remaining() < 4) {
        int newCapacity = this.capacity() * 2;
        byte[] newData = new byte[newCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.size());
        this.data = newData;
    }

    // Write the int value to the ByteVector
    ByteBuffer buffer = ByteBuffer.wrap(this.data, this.size(), 4);
    buffer.putInt(intValue);
    this.size += 4;

    return this;
}

/** 
 * Puts an int into this byte vector. The byte vector is automatically enlarged if necessary.
