public void abbreviate(final int nameStart, final StringBuffer buf) {
    try {
        if (nameStart == 0 || buf == null) {
            throw new IllegalArgumentException("The nameStart parameter or the buffer cannot be null");
        }
        int len = buf.length();
        if (nameStart < 0 || nameStart >= len) {
            throw new IndexOutOfBoundsException("The nameStart parameter is out of bounds");
        }
        // Get the first letter of the name
        String firstLetter = buf.substring(nameStart, nameStart + 1);
        // Check if the name is longer than one letter
        if (firstLetter.length() > 1) {
            // If the first letter is a vowel, abbreviate to the first letter and a dot
            if (firstLetter.matches("[aeiouAEIOU]")) {
                buf.delete(nameStart, len - 1);
                buf.append('.');
            } else {
                // If the first letter is not a vowel, abbreviate to the first letter and last two letters of the name
                String lastTwoLetters = buf.substring(nameStart + 1, nameStart + 3);
                buf.delete(nameStart, len - 2);
                buf.append(firstLetter + lastTwoLetters);
            }
        }
    } catch (StringIndexOutOfBoundsException | IllegalArgumentException e) {
        throw new RuntimeException("Error while abbreviating name", e);
    }
}

