public static boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices form a valid subgraph
    if (vertices == null || vertices.size() == 0) {
        return false;
    }
    Set<V> neighborSet = new HashSet<>();
    // Loop over all vertices in the given subgraph and get their neighbors
    for (V vertex : vertices) {
        Set<V> neighbors = graph.getNeighbors(vertex);
        neighborSet.addAll(neighbors);
    }
    // If the neighbor set is not a subset of the given vertices, the subgraph is not complete
    if (!neighborSet.containsAll(vertices)) {
        return false;
    }
    // Check if the subgraph is complete by comparing the number of edges to the number of vertices
    if (graph.getEdgeCount() != vertices.size() * (vertices.size() - 1)) {
        return false;
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check that the given vertices are in the graph
    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex " + vertex + " is not in the graph");
        }
    }

    // Check that the given vertices form a clique
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // If the input graph is null or the set of vertices is null or empty, return false
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return false;
    }

    // If the set of vertices is not a subset of the vertices in the graph, return false
    if (!vertices.containsAll(graph.vertexSet())) {
        return false;
    }

    // Check whether the clique property holds for all pairs of vertices in the subgraph
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }

    // If we reach this point, the subgraph induced by the given vertices is complete, i.e. a clique
    return true;
}

/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V, E>boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the number of vertices in the induced subgraph is equal to the number of vertices in the graph
    if (vertices.size() == graph.getNumVertices()) {
        // Check if the subgraph is connected
        if (graph.isConnected(vertices)) {
            // Check if the subgraph is a clique
            return graph.isClique(vertices);
        }
    }
    return false;
}

