public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty paths
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Build the resulting path by merging the path components with the relative path components
    StringBuilder resultBuilder = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        if (i == 0 && !pathComponents[i].isEmpty()) {
            resultBuilder.append(pathComponents[i]);
        } else if (relativePathComponents[i].isEmpty()) {
            continue;
        } else if (relativePathComponents[i].equals("..")) {
            if (resultBuilder.length() > 1) {
                // Remove the last component of the result
                int lastSlashIndex = resultBuilder.lastIndexOf("/");
                resultBuilder.delete(lastSlashIndex, resultBuilder.length());
            }
        } else {
            // Add the current component to the result
            if (resultBuilder.length() > 0) {
                resultBuilder.append("/");
            }
            resultBuilder.append(relativePathComponents[i]);
        }
    }

    return resultBuilder.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Handle edge case where path is null
    if (path == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }

    // Handle edge case where relativePath is null
    if (relativePath == null) {
        throw new IllegalArgumentException("Relative path cannot be null");
    }

    // Split path into individual components
    String[] pathComponents = path.split("/");
    // Split relativePath into individual components
    String[] relativePathComponents = relativePath.split("/");

    // Create a new list to hold the combined path components
    List<String> combinedPathComponents = new ArrayList<>();

    // Loop through each component of the path and relative path
    for (int i = 0; i < pathComponents.length && i < relativePathComponents.length; i++) {
        String currentPathComponent = pathComponents[i];
        String currentRelativePathComponent = relativePathComponents[i];

        // If the current path component is "..", remove the previous component from the combined path
        if (currentPathComponent.equals("..")) {
            if (combinedPathComponents.size() > 0) {
                combinedPathComponents.remove(combinedPathComponents.size() - 1);
            }
        // Else if the current relative path component is ".", do nothing
        } else if (currentRelativePathComponent.equals(".")) {
            // Do nothing
        // Else, add the current path component to the combined path
        } else {
            combinedPathComponents.add(currentPathComponent);
        }
    }

    // Add any remaining path components from the relative path
    for (int i = pathComponents.length; i < relativePathComponents.length; i++) {
        combinedPathComponents.add(relativePathComponents[i]);
    }

    // Join the combined path components using "/" and return the result
    return String.join("/", combinedPathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty strings
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        return null;
    }

    // Split the path and relative path into individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Initialize the result array with the first path component
    String[] result = new String[pathComponents.length + relativePathComponents.length];
    result[0] = pathComponents[0];

    // Apply the relative path to the result array
    int i = 1;
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            continue;
        } else if (component.equals("..")) {
            i--;
        } else {
            result[i++] = component;
        }
    }

    // Join the result array into a single string
    return String.join("/", result);
}

