public Edge edgeToNext() {
    // Check if either of the nodes is virtual
    if (this.isVirtual()) {
        // If the current node is virtual, return the edge from its real counterpart
        if (this.isVirtual()) {
            return this.getReal().edgeToNext();
        } else {
            return this.edgeTo(this.getReal());
        }
    } else {
        // If the next node is virtual, return the edge from the current node to its real counterpart
        if (this.next.isVirtual()) {
            return this.edgeTo(this.next.getReal());
        } else {
            return this.edgeTo(this.next);
        }
    }
}

public Edge edgeToNext() {
    // Check if the current node has a real counterpart
    if (this.isVirtual()) {
        this.getRealCounterpart().edgeToNext();
    }

    // Get the next node
    Node nextNode = getNextNode();

    // Connect the current node to the next node
    Edge edge = new Edge(this, nextNode);

    // Return the edge
    return edge;
}

public Edge edgeToNext() {
    // Check if there is a previous node
    if (previousNode == null) {
        throw new RuntimeException("No previous node to connect to.");
    }

    // Check if the previous node is virtual
    if (previousNode.isVirtual()) {
        // If the previous node is virtual, return the edge to its real counterpart
        return previousNode.getEdgeToReal();
    }

    // If the previous node is not virtual, return the edge to the current node
    return previousNode.getEdgeTo(this);
}

public Edge edgeToNext() {
    if (this.isVirtual()) {
        Node realNode = getRealNode();
        if (realNode != null) {
            return realNode.edgeToNext();
        }
    }

    return this.getAllEdges().stream()
            .filter(edge -> edge.getEndNode().equals(this.getNextNode()))
            .findFirst()
            .orElseThrow(() -> new IllegalStateException("Could not find next node"));
}

