    Node curNode = getCurrentNode();
    Node nextNode = getNextNode();
    if (curNode == null || nextNode == null) {
        throw new IllegalStateException("Cannot connect edges to null nodes");
    }
    Edge edge = new Edge(curNode, nextNode);
    return edge;
}

