public String buildContentRange() {
    // Calculate the total number of bytes in the file
    long totalBytes = getTotalBytes();

    // Calculate the range of bytes to send
    long startByte = getStartByte();
    long endByte = getEndByte();

    // Return the Content-Range header value
    return String.format("bytes %d-%d/%d", startByte, endByte, totalBytes);
}

private long getTotalBytes() {
    // Get the length of the file binary
    String fileBinary = getFileBinary();
    byte[] fileBytes = fileBinary.getBytes();
    return fileBytes.length;
}

private long getStartByte() {
    // Get the starting byte from the "Range" header parameter
    String rangeHeader = getRangeHeader();
    String[] headerParts = rangeHeader.split("=");
    String boundaryRange = headerParts[1];
    String[] startEndRange = boundaryRange.split("-");
    return Long.parseLong(startEndRange[0]);
}

private long getEndByte() {
    // Get the ending byte from the "Range" header parameter
    String rangeHeader = getRangeHeader();
    String[] headerParts = rangeHeader.split("=");
    String boundaryRange = headerParts[1];
    String[] startEndRange = boundaryRange.split("-");
    if (startEndRange.length > 1) {
        return Long.parseLong(startEndRange[1]);
    }
    // If there is no ending byte, set it to the total length of the file
    return getTotalBytes();
}

private String getRangeHeader() {
    // Get the "Range" header parameter from the HTTP request
    List<String> rangeHeaders = getRangeHeaders();
    for (String rangeHeader : rangeHeaders) {
        if (rangeHeader.startsWith("Range")) {
            return rangeHeader;
        }
    }
    // If there is no "Range" header, return an empty string
    return "";
}

