        int numPages = (int) Math.ceil((double) collectionSize / getPageSize());

        // Set the 'Content-Range' header value
        contentRange = String.format("items %d-%d/%d", getStartIndex(), getEndIndex(), collectionSize);

        // If there are additional pages after the current one, include them in the 'Content-Range' header
        if (getCurrentPage() + 1 < numPages) {
            contentRange += String.format(" items %d-%d/%d", getCurrentPage() * getPageSize() + 1, (getCurrentPage() + 1) * getPageSize(), collectionSize);
        }
    }

    return contentRange;
}

