    BufferedReader br = new BufferedReader(new FileReader(file));
    String line;
    while ((line = br.readLine()) != null) {
        // Check if the line is a thread snapshot
        if (line.startsWith("TS:")) {
            // Extract the thread snapshot information
            String[] tokens = line.split(",");
            long tid = Long.parseLong(tokens[1]);
            String state = tokens[2];
            long timestamp = Long.parseLong(tokens[3]);

            // Check if the thread is in the specified time range
            boolean inTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange: timeRanges) {
                if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
                    inTimeRange = true;
                    break;
                }
            }

            // If the thread is in the time range, add it to the list
            if (inTimeRange) {
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(tid, state, timestamp);
                threadSnapshots.add(threadSnapshot);
            }
        }
    }

    // Close the file
    br.close();

    // Return the list of thread snapshots
    return threadSnapshots;
}

