                continue;
            }

            ProfileAnalyzeTimeRange timeRange = timeRanges.get(0);
            long timeStamp = Long.parseLong(fields[0]);
            if (timeStamp >= timeRange.getStartTime() && timeStamp <= timeRange.getEndTime()) {
