    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(" ");
            if (parts.length != 3) {
                continue;
            }
            long time = Long.parseLong(parts[0]);
            String type = parts[1];
            String data = parts[2];
            ProfileAnalyzeTimeRange timeRange = timeRanges.stream().filter(r -> r.timeRange.contains(time)).findFirst().orElse(null);
            if (timeRange == null) {
                continue;
            }
            switch (type) {
                case "START":
                    threadSnapshots.add(new ThreadSnapshot(timeRange, data));
                    break;
                case "END":
                    ThreadSnapshot lastSnapshot = threadSnapshots.get(threadSnapshots.size() - 1);
                    if (lastSnapshot.getTimestamp() == time && lastSnapshot.getData().equals(data)) {
                        threadSnapshots.remove(threadSnapshots.size() - 1);
                    }
                    break;
            }
        }
    }
    return threadSnapshots;
}

